import iterCartesianProduct = require( './index' );


// TESTS //

// The function returns an iterator...
{
	iterCartesianProduct( [ 1, 2, 3 ], [ 4, 5 ] ); // $ExpectType Iterator
	iterCartesianProduct( new Float64Array( [ 1, 2 ] ), new Float64Array( [ 3, 4 ] ) ); // $ExpectType Iterator
	iterCartesianProduct( { 'length': 2, '0': 1, '1': 2 }, [ 3, 4 ] ); // $ExpectType Iterator
}

// The compiler throws an error if the function is provided a first argument which is not an array-like object...
{
	iterCartesianProduct( 1, [ 1, 2 ] ); // $ExpectError
	iterCartesianProduct( true, [ 1, 2 ] ); // $ExpectError
	iterCartesianProduct( false, [ 1, 2 ] ); // $ExpectError
	iterCartesianProduct( null, [ 1, 2 ] ); // $ExpectError
	iterCartesianProduct( void 0, [ 1, 2 ] ); // $ExpectError
	iterCartesianProduct( {}, [ 1, 2 ] ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not an array-like object...
{
	iterCartesianProduct( [ 1, 2 ], 1 ); // $ExpectError
	iterCartesianProduct( [ 1, 2 ], true ); // $ExpectError
	iterCartesianProduct( [ 1, 2 ], false ); // $ExpectError
	iterCartesianProduct( [ 1, 2 ], null ); // $ExpectError
	iterCartesianProduct( [ 1, 2 ], void 0 ); // $ExpectError
	iterCartesianProduct( [ 1, 2 ], {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	iterCartesianProduct(); // $ExpectError
	iterCartesianProduct( [ 1, 2 ] ); // $ExpectError
	iterCartesianProduct( [ 1, 2 ], [ 3, 4 ], [ 5, 6 ] ); // $ExpectError
}
